vec2 R;
#define T iTime
#define I iFrame
#define Main void mainImage(out vec4 Q, in vec2 U)
#define A(U) texture(iChannel0,(U)/R)
#define B(U) texture(iChannel1,(U)/R)
#define C(U) texture(iChannel2,(U)/R)
#define D(U) texture(iChannel3,(U)/R)
#define ei(a) mat2(cos(a),sin(a),-sin(a),cos(a))
vec2 norm (vec2 v){
    if (length(v) == 0.) return vec2(0);
    else return normalize(v);
}
vec4 hash(vec4 p) {
                const vec4 k = vec4(0.1031, 0.11369, 0.13787, 0.16379); 
                p = fract(p * k);                                       
                p += dot(p, p.wxyz + k);                                
                p = fract((p.xxyz + p.yzww) * p.zyxw);                  
                return fract(sin(p) * 43758.5453);                      
            }
float ln (vec3 u, vec3 a, vec3 b) {
    return length(u-a-(b-a)*clamp(dot(u-a,b-a)/dot(b-a,b-a),0.,1.));
}
float ln (vec2 u, vec2 a, vec2 b) {
    return length(u-a-(b-a)*clamp(dot(u-a,b-a)/dot(b-a,b-a),0.,.75));
}

vec2 scene (vec3 u) {
                u.y +=.7;
                float d = 1e9;
                float a = 0.;
                for (float i = 0.; i < 10.; i++) {
                    float d1 = ln(u,vec3(0),vec3(0,-.4*exp2(-.5*(i-1.)),0))-.05*exp2(-.5*i);
                    if (d1 < d) {
                        a = i;
                        d = d1;
                    }
                    u.xy *= ei(-.4*sqrt(i));
                    u.xz = abs(u.xz);
                    u.xz *= ei(.4);
                    u.xy *= ei(-.2*sqrt(i));
                    //u.yx *= ei(.3*sqrt(i));
                    u.y -= .4*exp2(-.5*i);
                }
                return vec2(d,a);
            }

Main {
    R = iResolution.xy;
    Q = A(U);
    float m = 1000.;
    vec4 h = hash(vec4(iFrame,-1,1,1));
    vec3 p = vec3(.8*R.x,.5*R.y,0);
    vec3 v = vec3(-2.,0,0);
    p.xy += (h.xy*2.-1.)*10.;
    for (float i = 0.; i < 300.;i++) {
        vec3 o = p;
        v += (hash(vec4(iFrame,i,1,1)).xyz*2.-1.);
        p += 5000./R.x*v*m*inversesqrt(1.+m*m*dot(v,v));

        if (length(o.xy-p.xy)>0.)
        Q += exp(-i/300.*i/300.)*exp(2.*i/300.)*exp(-2.*ln(U,o.xy,p.xy));

    }

}
